/**
 * Normalize district string or ID to standard lowercase format
 */
function normalizeDistrictId(districtId) {
  if (!districtId) return '';
  const clean = String(districtId).toLowerCase().trim().replace(/[^a-z0-9]/g, '');
  if (clean.includes('chengalpattu') || clean.includes('chengalpet')) return 'chengalpattu';
  if (clean.includes('coimbatore') || clean.includes('kovai')) return 'coimbatore';
  if (clean.includes('kanyakumari') || clean.includes('kanniyakumari')) return 'kanniyakumari';
  if (clean.includes('kanchipuram') || clean.includes('kancheepuram')) return 'kancheepuram';
  if (clean.includes('namakkal')) return 'namakkal';
  if (clean.includes('thiruvallur') || clean.includes('tiruvallur')) return 'tiruvallur';
  if (clean.includes('tiruchirappalli') || clean.includes('trichy') || clean.includes('tiruchirapalli')) return 'tiruchirappalli';
  if (clean.includes('tirunelveli') || clean.includes('nellai')) return 'tirunelveli';
  if (clean.includes('thoothukudi') || clean.includes('tuticorin')) return 'thoothukudi';
  if (clean.includes('madurai')) return 'madurai';
  if (clean.includes('salem')) return 'salem';
  return clean;
}

/**
 * Retrieve villages for a given district and subdivision (taluk).
 * Handles direct ID match, substring match, and fallback.
 */
export function getVillagesForSubdivision(districtId, subdivisionId) {
  if (!districtId && !subdivisionId) return [];
  const cleanDist = normalizeDistrictId(districtId);
  const cleanSub = subdivisionId ? String(subdivisionId).toLowerCase().trim() : '';

  // 1. Direct match by exact subdivisionId
  if (cleanSub && VILLAGES_BY_SUBDIVISION[cleanSub]) {
    return VILLAGES_BY_SUBDIVISION[cleanSub];
  }

  // 2. Suffix or substring match on subdivision keys
  if (cleanSub) {
    const keys = Object.keys(VILLAGES_BY_SUBDIVISION);
    // Exact suffix match: e.g. 'sendamangalam' matching 'nmk_sendamangalam'
    const suffixMatch = keys.find(k => {
      const parts = k.split('_');
      const suffix = parts.slice(1).join('_');
      return suffix === cleanSub || cleanSub.endsWith(suffix) || suffix.endsWith(cleanSub);
    });
    if (suffixMatch) return VILLAGES_BY_SUBDIVISION[suffixMatch];

    // Contains match
    const subMatch = keys.find(k => k.includes(cleanSub) || cleanSub.includes(k));
    if (subMatch) return VILLAGES_BY_SUBDIVISION[subMatch];
  }

  // 3. Fallback: return villages from first subdivision of the district
  if (cleanDist) {
    const distMatchKey = Object.keys(VILLAGES_BY_SUBDIVISION).find(k => {
      const prefix = k.split('_')[0];
      return cleanDist.startsWith(prefix) || prefix.startsWith(cleanDist.slice(0, 3));
    });
    if (distMatchKey) return VILLAGES_BY_SUBDIVISION[distMatchKey];
  }

  return [];
}

/**
 * Retrieve all unique villages across all subdivisions in a district
 */
export function getAllVillagesForDistrict(districtId) {
  if (!districtId) return [];
  const cleanDist = normalizeDistrictId(districtId);
  const result = [];
  const seen = new Set();

  Object.entries(VILLAGES_BY_SUBDIVISION).forEach(([subId, villages]) => {
    if (subId.startsWith(cleanDist.slice(0, 3))) {
      villages.forEach(v => {
        if (!seen.has(v.name)) {
          seen.add(v.name);
          result.push(v);
        }
      });
    }
  });

  return result;
}
